    if part == "method":
        return ctx.request.method.upper()
    value = ctx.request.headers.get(part[len("header:"):])
    if value is None:
        return None
    value = value.strip(" \t")
    return value or None


def _key(ctx, limit, client):
    values = []
    for part in limit.key:
        v = _part(ctx, part, client)
        if v is None:
            return None
        values.append(v)
    return tuple(values)


