    ts = ctx.request.ts_ms
    state.now = ts if state.now is None else max(state.now, ts)
    now = state.now
    if not state.limits:
        return None
    method = ctx.request.method.upper()
    client = client_address(ctx.request, state.trusted)
    checks = []  # (index, limit, limit state, cost, allowed)
    for i, limit in enumerate(state.limits):
