            continue
        if limit.methods is not None and method not in limit.methods:
            continue
        key = _key(ctx, limit, client)
        if key is None:
            continue
        if exempted(client, limit.exempt):
            continue
        s = state.buckets[i].get(key)
        if s is None:
            s = state.buckets[i][key] = new_state(limit, now)
